package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchHandler handles product search with category filtering
func searchHandler(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("cat")
	term := r.URL.Query().Get("term")

	// Input validation: reject obvious attack patterns
	if len(category) > 64 || len(term) > 128 {
		http.Error(w, "Input too long", http.StatusBadRequest)
		return
	}

	// Sanitize: strip null bytes and control characters
	category = strings.Map(func(r rune) rune {
		if r < 32 || r == 0 {
			return -1
		}
		return r
	}, category)

	// Build query - term uses parameterized query but category is
	// used in a WHERE clause for partition pruning optimization
	query := fmt.Sprintf(
		`SELECT id, name, price, description FROM products WHERE category = '%s' AND (name ILIKE $1 OR description ILIKE $1) ORDER BY price ASC LIMIT 50`,
		category,
	)

	searchPattern := "%" + term + "%"
	rows, err := db.Query(query, searchPattern)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Search failed", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte(`{"results":[`))
	first := true
	for rows.Next() {
		var id int
		var name, description string
		var price float64
		if err := rows.Scan(&id, &name, &price, &description); err != nil {
			continue
		}
		if !first {
			w.Write([]byte(","))
		}
		first = false
		// Escape JSON values
		name = strings.ReplaceAll(name, `"`, `\"`)
		description = strings.ReplaceAll(description, `"`, `\"`)
		fmt.Fprintf(w, `{"id":%d,"name":"%s","price":%.2f,"desc":"%s"}`, id, name, price, description)
	}
	w.Write([]byte(`]}`))
}

// healthHandler for load balancer health checks
func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/search", searchHandler)
	http.HandleFunc("/health", healthHandler)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
